import { test, expect } from '../../fixtures/index.js';
import { meta } from 'reporting-labs';
import { AccountRecordPage } from '../../pages/AccountRecordPage.js';
import { NewContactDialog } from '../../pages/NewContactDialog.js';
import { expectFieldError, selectPicklist, showRelatedList, waitForSpinners } from '../../support/lightning.js';
import { soqlCount } from '../../support/api.js';

test.describe('SF-219 Create Contact with invalid phone format (not 10 digits) is rejected with validation error', () => {
  test.describe.configure({ mode: 'parallel' });

  test(
    'TC-SF-219-009 Create Contact with invalid phone format (not 10 digits) is rejected with validation error',
    { tag: ['@negative', '@P2', '@SF-219', '@persona:system-admin', '@mandatory'] },
    async ({ page, data, sf }) => {
      meta({
        priority: 'P2',
        severity: 'minor',
        feature: 'Contact',
        story: 'SF-219',
        owner: 'qa-agent',
        testCase: 'TC-SF-219-009',
      });
      const accountRecordPage = new AccountRecordPage(page);
      const newContactDialog = new NewContactDialog(page);
      const lastName = data.unique('last-name');
      await data.create('account-contact', ['Account']);
      await test.step('1. Navigate to the Account record page and click New Contact', async () => {
        // Expected (DECLARED_CONFIG; SF-219#AC5, ValidationRule:Contact.Phone_Must_Be_10_Digits, OC-007): Contact creation modal or page opens
        await accountRecordPage.open(data.id('Account'));
        await showRelatedList(accountRecordPage.contactsRelatedList, accountRecordPage.relatedTab);
        await accountRecordPage.contactsNewButton.click();
        await expect(newContactDialog.root).toBeVisible();
      });
      await test.step("2. Enter Last Name 'BadPhoneContact', set Lead Source to 'Word of mouth', enter Phone '55512345' (8 digits), click Save", async () => {
        // Expected (DECLARED_CONFIG; ValidationRule:Contact.Phone_Must_Be_10_Digits, SF-219#AC5, BRD-CON-012#BR-04, OC-007): Contact is not saved and validation error 'Phone must be exactly 10 digits.' is displayed on the Phone field
        await newContactDialog.lastName.fill(lastName);
        await selectPicklist(page, newContactDialog.leadSource, 'Word of mouth');
        await newContactDialog.phone.fill('55512345');
        await newContactDialog.saveButton.click();
        await waitForSpinners(page);
        expect(await soqlCount(sf, 'Contact', 'LastName', lastName)).toBe(0);
        await expectFieldError(newContactDialog.phone, 'Phone must be exactly 10 digits.'); // message of rule Contact.Phone_Must_Be_10_Digits (org snapshot)
      });
    },
  );
});
